// RunAll executes all preflight checks and returns any errors found
// If checkConnectivity is true, also checks SSH connectivity to remote servers
func RunAll(cfg *config.Config) []error {
	var errors []error

	// Core checks (always run)
	checks := []func(*config.Config) []error{
		checkRsyncBinary,
		checkBackupBasePath,
		checkSSHKeys,
		checkCronSchedules,
	}

	for _, check := range checks {
		if errs := check(cfg); len(errs) > 0 {
			errors = append(errors, errs...)
		}
	}

	return errors
}

// RunAllWithConnectivity runs all checks including SSH connectivity
func RunAllWithConnectivity(cfg *config.Config) []error {
	errors := RunAll(cfg)

	if errs := checkSSHConnectivity(cfg); len(errs) > 0 {
		errors = append(errors, errs...)
	}

	return errors
}
